mapper.select:
SELECT COUNT(*)
FROM child c
         INNER JOIN child_parent cp ON c.child_id = cp.child_id
WHERE c.child_id = #{childId}
  AND cp.member_id = #{memberId}
  AND c.status = 'ACTIVE'

SELECT CASE
           WHEN EXISTS (
               SELECT 1
               FROM financial_account
               WHERE child_id = #{childId}
           )
               OR EXISTS (
                   SELECT 1
                   FROM financial_goal
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM allowance_request
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM account_balance_snapshot
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM account_transaction
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM financial_transfer
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM auto_transfer_schedule
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM asset_report
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM time_capsule
                   WHERE child_id = #{childId}
               )
               OR EXISTS (
                   SELECT 1
                   FROM mission
                   WHERE child_id = #{childId}
               )
               THEN 1
           ELSE 0
           END
